// Arma UNA fila de metricas por consulta (CA-01..CA-05). No inventa datos.
const PRINCIPAL = { proveedor: 'OpenAI', modelo: 'gpt-5.6-luna' };
const ALTERNO   = { proveedor: 'Gemini', modelo: 'models/gemini-3.6-flash' };
const j = $json;
const wh = $('Webhook').first().json;
const ini = $('Iniciar métricas').first().json;
const ahora = Date.now();
const esError = j.success === false && String(j.proveedor_respuesta || '').startsWith('N/A');
let usoFailover = false;
try { usoFailover = $('Marca inicio alterno').first() != null; } catch (e) {}
let estado, proveedor, modelo, latProv = null, errMsg = null;
if (esError) {
  estado = 'error'; proveedor = 'ninguno'; modelo = null;
  errMsg = j.error_detalle ? String(j.error_detalle).slice(0, 500) : null;
} else {
  const esAlterno = String(j.proveedor_respuesta || '').startsWith('Gemini');
  if (esAlterno) usoFailover = true;
  const dest = esAlterno ? ALTERNO : PRINCIPAL;
  proveedor = dest.proveedor; modelo = dest.modelo;
  let ini2 = Number(ini.t_inicio);
  if (esAlterno) { try { ini2 = Number($('Marca inicio alterno').first().json.t_inicio_alterno); } catch (e) { ini2 = NaN; } }
  if (j.t_fin_agente && ini2) latProv = Number(j.t_fin_agente) - ini2;
  const riesgo = j.output && j.output.risk;
  estado = riesgo === 'HIGH_RISK' ? 'bloqueada' : (esAlterno ? 'ok_failover' : 'ok');
}
return [{ json: {
  correlation_id: ini.correlation_id,
  session_id: (wh.body && wh.body.sessionId) || wh.sessionId || null,
  execution_id: String($execution.id),
  latencia_total_ms: ahora - Number(ini.t_inicio),
  latencia_proveedor_ms: latProv,
  tokens_entrada: null, tokens_salida: null, tokens_total: null,
  tokens_origen: 'no_disponible',
  proveedor, modelo, uso_failover: usoFailover, estado, error_mensaje: errMsg,
  costo_usd: null, costo_origen: 'no_calculado'
} }];
